"use client";
import * as React from "react";
import { LayoutGroup, motion, useReducedMotion } from "motion/react";
import { cn } from "../lib/cn";
import { useControllableState } from "../lib/hooks";
import type { SegmentedProps } from "../components/segmented";

export interface MotionSegmentedProps extends SegmentedProps {
  /** Eigen id wanneer er meerdere schakelaars naast elkaar staan. */
  layoutId?: string;
}

/**
 * MotionSegmented — dezelfde API als Segmented, maar de actieve achtergrond
 * schuift mee naar de knop die je kiest in plaats van te verspringen.
 */
export const MotionSegmented = React.forwardRef<HTMLDivElement, MotionSegmentedProps>(function MotionSegmented(
  { options, value, defaultValue, onValueChange, size = "md", block, layoutId, className, ...rest },
  ref
) {
  const auto = React.useId();
  const id = layoutId ?? `pxui-segmented-${auto}`;
  const reduced = useReducedMotion();

  const [current, setCurrent] = useControllableState<string | undefined>({
    value,
    defaultValue: defaultValue ?? options[0]?.value,
    onChange: (next) => next !== undefined && onValueChange?.(next),
  });

  return (
    <LayoutGroup id={id}>
      <div
        ref={ref}
        role="tablist"
        className={cn(
          "pxui-segmented",
          `pxui-segmented-${size}`,
          block && "pxui-segmented-block",
          "pxui-motion-segmented",
          className
        )}
        {...rest}
      >
        {options.map((option) => {
          const active = current === option.value;
          return (
            <button
              key={option.value}
              type="button"
              role="tab"
              aria-selected={active}
              aria-label={option.ariaLabel}
              disabled={option.disabled}
              data-state={active ? "active" : "inactive"}
              className="pxui-segmented-item"
              onClick={() => setCurrent(option.value)}
            >
              {active && (
                <motion.span
                  layoutId="pxui-segmented-indicator"
                  className="pxui-motion-segmented-indicator"
                  transition={
                    reduced ? { duration: 0 } : { type: "spring", stiffness: 480, damping: 38, mass: 0.7 }
                  }
                />
              )}
              {option.icon && <span className="pxui-segmented-icon">{option.icon}</span>}
              {option.label}
            </button>
          );
        })}
      </div>
    </LayoutGroup>
  );
});

/* ==================== Motion-laag (optioneel) ==================== */
/* Alleen de extra's die de motion-varianten nodig hebben. De panelen zelf
   gebruiken dezelfde klassen als Drawer en Segmented. */

/* De CSS-keyframes van Drawer uitzetten: motion regelt de beweging. */
.pxui-motion-drawer { animation: none !important; }

.pxui-motion-handle {
  display: grid; place-items: center; padding: 10px 0 4px;
  cursor: grab; touch-action: none; flex: none;
}
.pxui-motion-handle:active { cursor: grabbing; }
.pxui-motion-handle > span {
  display: block; width: 42px; height: 4px;
  border-radius: var(--r-full); background: var(--border-strong);
}
.pxui-motion-handle-vertical { padding: 4px 10px 4px 4px; }
.pxui-motion-handle-vertical > span { width: 4px; height: 42px; }

/* ---------- ReorderList ---------- */
.pxui-reorder {
  display: flex; flex-direction: column; gap: 8px;
  list-style: none; margin: 0; padding: 0;
}
.pxui-reorder-x { flex-direction: row; }

.pxui-reorder-item {
  position: relative; display: flex; align-items: center; gap: 10px;
  padding: 11px 13px; background: var(--surface);
  border: 1px solid var(--border); border-radius: var(--r-md);
  cursor: grab; touch-action: none; user-select: none;
}
.pxui-reorder-item:active { cursor: grabbing; }
.pxui-reorder-item:has(.pxui-reorder-handle) { cursor: default; }

.pxui-reorder-handle {
  display: inline-grid; place-items: center; flex: none;
  color: var(--text-3); cursor: grab; touch-action: none;
}
.pxui-reorder-handle:active { cursor: grabbing; }
.pxui-reorder-content { flex: 1; min-width: 0; }

/* ---------- MotionSegmented ---------- */
/* De meeschuivende achtergrond vervangt de statische van Segmented. */
.pxui-motion-segmented .pxui-segmented-item { position: relative; }
.pxui-motion-segmented .pxui-segmented-item[data-state="active"] {
  background: transparent; box-shadow: none;
}
.pxui-motion-segmented-indicator {
  position: absolute; inset: 0; z-index: 0;
  border-radius: var(--r-xs); background: var(--surface); box-shadow: var(--sh-xs);
}
.pxui-motion-segmented .pxui-segmented-item > *:not(.pxui-motion-segmented-indicator) {
  position: relative; z-index: 1;
}
